for (def group : params.groups.entrySet()) {
  if (!(ctx[group.getKey()] instanceof Map)) { throw new IllegalArgumentException('invalid export group'); }
  def value = ctx[group.getKey()];
  if (value.size() != group.getValue().size()) { throw new IllegalArgumentException('invalid export fields'); }
  for (def field : group.getValue()) {
    if (!value.containsKey(field) || value[field] == null) { throw new IllegalArgumentException('missing export field'); }
  }
}
for (def group : params.fixed.entrySet()) {
  for (def field : group.getValue().entrySet()) {
    if (!field.getValue().equals(ctx[group.getKey()][field.getKey()])) { throw new IllegalArgumentException('invalid export constant'); }
  }
}
if (!(ctx['@timestamp'] instanceof String)) { throw new IllegalArgumentException('invalid export timestamp'); }
for (def field : ['id','hash']) {
  def value = ctx.event[field];
  if (!(value instanceof String) || value.length() != 64) { throw new IllegalArgumentException('invalid export digest'); }
  for (int i = 0; i < value.length(); i++) {
    if ('0123456789abcdef'.indexOf(value.substring(i,i+1)) < 0) { throw new IllegalArgumentException('invalid export digest'); }
  }
}
if (!ctx.event.id.equals(ctx['_id'])) { throw new IllegalArgumentException('document id differs from event id'); }
if (!params.rules.contains(ctx.rule.id) || !ctx.rule.id.equals(ctx.event.action)) { throw new IllegalArgumentException('invalid export rule'); }
if (!params.outcomes.contains(ctx.event.outcome) || !params.severities.contains(ctx.postgres_audit_guard.severity)) { throw new IllegalArgumentException('invalid export enum'); }
if (!(ctx.rule.name instanceof String) || ctx.rule.name.length() == 0 || ctx.rule.name.length() > 128) { throw new IllegalArgumentException('invalid rule name'); }
if (!(ctx.postgres_audit_guard.sqlstate instanceof String)) { throw new IllegalArgumentException('invalid SQLSTATE'); }
def state = ctx.postgres_audit_guard.sqlstate;
if (state.length() != 0 && state.length() != 5) { throw new IllegalArgumentException('invalid SQLSTATE length'); }
for (int i = 0; i < state.length(); i++) {
  if ('0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'.indexOf(state.substring(i,i+1)) < 0) { throw new IllegalArgumentException('invalid SQLSTATE characters'); }
}
